import{Q as e,X as t,ft as n,n as r}from"./chunks/framework.aUqElhQb.js";var i=JSON.parse(`{"title":"Environment Files","description":"","frontmatter":{"id":"guide.environment-files","title":"Environment Files","describes":["proposal.0001","proposal.0002","proposal.0004"]},"headers":[],"relativePath":"guides/environment-files.md","filePath":"guides/environment-files.md"}`),a={name:`guides/environment-files.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e('<h1 id="environment-files" tabindex="-1">Environment Files <a class="header-anchor" href="#environment-files" aria-label="Permalink to “Environment Files”">​</a></h1><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to “What it does”">​</a></h2><p>Before <code>bento run</code> starts a script, it loads the project&#39;s <code>.env</code> files into that launch&#39;s environment, beneath the variables <code>bento</code> was started with. Bento reads the files your project already has; nothing needs converting to a Bento-specific format.</p><p>The project is the nearest directory, from the script&#39;s own directory upward, that holds a <code>package.json</code>. Bento reads <code>.env</code>, <code>.env.&lt;mode&gt;</code>, and <code>.env.local</code> from that directory, so running a script from another directory still loads its own project&#39;s files. If no <code>package.json</code> is found, Bento reports an error.</p><h2 id="how-to-use-it" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it" aria-label="Permalink to “How to use it”">​</a></h2><h3 id="write-env-files" tabindex="-1">Write <code>.env</code> files <a class="header-anchor" href="#write-env-files" aria-label="Permalink to “Write .env files”">​</a></h3><ul><li>Write one <code>NAME=value</code> per line. Blank lines and lines starting with <code>#</code> are ignored, and <code>export NAME=value</code> is accepted.</li><li>Unquoted values are trimmed, and a <code>#</code> starts a comment. Quote any value that contains <code>#</code>.</li><li><code>&#39;single&#39;</code> and <code>`backtick`</code> quotes keep everything inside them literally.</li><li><code>&quot;double&quot;</code> quotes understand <code>\\n</code>, <code>\\r</code>, <code>\\t</code>, <code>\\&quot;</code>, and <code>\\\\</code>. Any other backslash stays as written.</li><li>A quoted value may span several lines.</li><li>Nothing is expanded or executed: <code>$HOME</code>, <code>${HOME}</code>, <code>$(command)</code>, and backticks stay literal text.</li><li>A malformed line stops the launch with the file and line number, as in <code>.env:2: quoted value is never closed</code>. The value on that line, and the rest of the file, are never printed, because environment files often hold secrets.</li></ul><h3 id="mode-and-precedence" tabindex="-1">Mode and precedence <a class="header-anchor" href="#mode-and-precedence" aria-label="Permalink to “Mode and precedence”">​</a></h3><p>Bento picks the mode once per launch:</p><ol><li>the <code>NODE_ENV</code> in the environment <code>bento</code> was started with;</li><li>otherwise the <code>NODE_ENV</code> in <code>.env</code>;</li><li>otherwise the launch default: <code>development</code> for <code>bento run --watch</code>, and no mode for <code>bento run</code>.</li></ol><p>Then it builds the environment from these layers, each overriding the ones above it:</p><table tabindex="0"><thead><tr><th>Layer</th><th>Source</th></tr></thead><tbody><tr><td>1</td><td><code>.env</code></td></tr><tr><td>2</td><td><code>.env.&lt;mode&gt;</code>, only when there is a mode</td></tr><tr><td>3</td><td><code>.env.local</code></td></tr><tr><td>4</td><td>Variables in the environment <code>bento</code> started with</td></tr></tbody></table><p>Missing files are skipped. A <code>NODE_ENV</code> set inside <code>.env.&lt;mode&gt;</code> or <code>.env.local</code> changes that variable but not which files load.</p><p>The effective <code>NODE_ENV</code> is part of the launch environment. A watch launch gets <code>NODE_ENV=development</code> even when the project has no <code>.env</code> files at all. The default never replaces a value that you or a file set.</p><h3 id="start-bento-from-another-program" tabindex="-1">Start <code>bento</code> from another program <a class="header-anchor" href="#start-bento-from-another-program" aria-label="Permalink to “Start bento from another program”">​</a></h3><p>Every <code>bento run</code> loads the files for itself, whoever starts it: your shell, a package script, a task runner, or a shell script. Every variable the starting program passes counts as one you set and overrides every file, even when that program loaded the value from the same <code>.env</code> file. A program that runs <code>bento run --watch server.ts</code> with <code>DATABASE_URL</code> already in its environment therefore keeps that <code>DATABASE_URL</code>, whatever <code>.env.development</code> says. To let the mode file decide, do not export the variable to <code>bento</code>.</p><h3 id="what-the-script-sees" tabindex="-1">What the script sees <a class="header-anchor" href="#what-the-script-sees" aria-label="Permalink to “What the script sees”">​</a></h3><p>Loading <code>.env</code> files never changes the environment of the process that started Bento or of a Rust host embedding it. A loaded value is not automatically visible to guest code either: a script sees only the variables <code>--allow-env</code> grants, whether they came from your environment or from a file. <a href="./running-with-bento#grant-capabilities">Running with Bento</a> describes the grant.</p><p>Bento reads <code>.env</code> files when a launch starts. To pick up a change, restart the launch; watch mode does not reload them.</p><h2 id="worked-example" tabindex="-1">Worked example <a class="header-anchor" href="#worked-example" aria-label="Permalink to “Worked example”">​</a></h2><p>The project holds <code>.env</code> containing <code>PORT=1612</code> and <code>DATABASE_URL=db/data.db</code>, and <code>.env.development</code> containing <code>DATABASE_URL=db/development.db</code>. Nothing is exported, and each command passes <code>--allow-env=PORT,DATABASE_URL,NODE_ENV</code> so the script can see the three variables:</p><ol><li><code>bento run server.ts</code> has no mode, because <code>bento run</code> has no default and neither your environment nor <code>.env</code> sets <code>NODE_ENV</code>. The script sees <code>PORT=1612</code> and <code>DATABASE_URL=db/data.db</code>, and no <code>NODE_ENV</code>.</li><li><code>bento run --watch server.ts</code> selects the <code>development</code> mode, loads <code>.env</code> and then <code>.env.development</code>, and starts the script with <code>PORT=1612</code>, <code>DATABASE_URL=db/development.db</code>, and <code>NODE_ENV=development</code>.</li><li><code>DATABASE_URL=db/mine.db bento run --watch server.ts</code> keeps <code>DATABASE_URL=db/mine.db</code>, because a value you set always beats the files.</li><li><code>NODE_ENV=test bento run server.ts</code> selects the <code>test</code> mode and loads <code>.env.test</code> after <code>.env</code>, if the project has one.</li></ol><h2 id="limits-and-edge-cases" tabindex="-1">Limits and edge cases <a class="header-anchor" href="#limits-and-edge-cases" aria-label="Permalink to “Limits and edge cases”">​</a></h2><ul><li>Bento does not reload <code>.env</code> files while a launch runs, including in watch mode.</li><li>A mode is used as part of a file name, so a <code>NODE_ENV</code> containing <code>/</code> is rejected. An empty <code>NODE_ENV</code> that you set means no mode, and Bento leaves it empty.</li><li>Bento needs every environment variable it starts with to be valid UTF-8, and reports the first one that is not by name.</li></ul>',24)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};